INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (24, 'loginBrandPanel.subheadline', 'vodafonepay.com.tr''deki kampanyaları, sayfaları, duyuruları ve SSS''leri tek yerden yönetin. Onay akışı, roller ve denetim kaydı kutudan çıkar — ne göç, ne bağımlılık.', 'Run every campaign, page, announcement and FAQ on vodafonepay.com.tr from one place. Approval workflows, roles and audit trails come built in — no migration, no lock-in.', '2026-08-15 20:40:59.952+00', '2026-08-14 11:04:14.977+00', false);
