INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (213, 'contentManagement.siteRoutesHint', 'Bunlar Pages koleksiyonunda değil, geliştirici tarafından kodla oluşturulmuş sayfalar — burada sadece referans için listeleniyor, düzenlenemezler. İçeriklerinin çoğu yine de CMS''ten geliyor (örn. bu sayfalardaki SSS/kampanya bölümleri).', 'These aren''t Pages documents — they''re pages built by a developer in code, listed here for reference only, not editable. Most of their content still comes from the CMS (e.g. the FAQ/campaign sections on these pages).', '2026-08-19 08:02:16.213+00', '2026-08-19 08:02:16.213+00', false);
