INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (218, 'feesAndLimits.intro', 'Ücret Tablosu ve Limit Tabloları artık bu tek sayfadan yönetiliyor — sekmeler arasında geçiş yapın, bir satıra tıklayıp düzenleyin, ya da aşağıdaki sürükle-bırak aracıyla sırasını değiştirin.', 'Fee Rows and Limit Tables are now managed from this single page — switch between the tabs, click a row to edit it, or reorder with the drag-and-drop tool below.', '2026-08-20 12:09:45.918+00', '2026-08-20 12:09:45.917+00', false);
