INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (240, 'accessMatrix.intro', 'Her rolün her koleksiyonda ne yapabildiğini gösteren tablo — görüntüle/oluştur/düzenle/yayınla/sil. access/roles.ts''teki gerçek yetki mantığından üretilir; ikisi ayrışamaz.', 'What each role can do in each collection — view/create/update/publish/delete. Generated from the same permission logic in access/roles.ts, so the two can''t drift apart.', '2026-08-25 03:48:36.036+00', '2026-08-25 03:48:36.036+00', false);
