INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (186, 'lockedAccounts.bannerCta', 'Kilitli hesapları görüntüle →', 'View locked accounts →', '2026-08-25 06:02:20.422+00', '2026-08-15 20:37:28.244+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (246, 'accountForm.username', 'Kullanıcı Adı (LDAP)', 'Username (LDAP)', '2026-08-25 06:33:11.76+00', '2026-08-25 06:33:11.76+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (80, 'accountForm.roleDescription', 'vodafone.local LDAP / AccessPoint rolünüz. Rol AccessPoint üzerinden talep edilir ve LDAP grubuna göre atanır — bu panelde kimse (siz dahil) değiştiremez.', 'Your vodafone.local LDAP / AccessPoint role. Roles are requested through AccessPoint and assigned from your LDAP group — nobody, including you, can change it in this panel.', '2026-08-25 06:33:11.814+00', '2026-08-14 18:08:15.921+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (247, 'roleAwarePublishButton.forceRecommended', 'Bu kampanya yayında ve üzerinde değişiklik yaptınız. Önerilen yol: önce yayından kaldırın, düzenleyin, tekrar onaya gönderin. Acil bir düzeltmeyse inceleme adımını atlayarak doğrudan canlıya uygulayabilirsiniz.', 'This campaign is live and you''ve changed it. Recommended: unpublish, edit, send back through review. If it''s urgent, you can skip review and apply the change directly to the live site.', '2026-08-25 09:04:11.824+00', '2026-08-25 09:04:11.823+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (248, 'roleAwarePublishButton.forceEdit', 'Acil: Doğrudan Canlıya Uygula', 'Urgent: Apply Live Now', '2026-08-25 09:04:11.867+00', '2026-08-25 09:04:11.867+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (249, 'roleAwarePublishButton.forceEditing', 'Uygulanıyor…', 'Applying…', '2026-08-25 09:04:11.876+00', '2026-08-25 09:04:11.876+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (250, 'roleAwarePublishButton.forceHeading', 'İnceleme adımını atlıyorsunuz', 'You are skipping the review step', '2026-08-25 09:04:11.885+00', '2026-08-25 09:04:11.885+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (251, 'roleAwarePublishButton.forceBody', 'Bu değişiklik hiçbir Checker onayından geçmeden, şu anda yayında olan kampanyaya doğrudan uygulanacak ve sitede anında görünecek. İşlem, kim tarafından ve ne zaman yapıldığıyla birlikte denetim kaydına yazılır.', 'This change will be applied straight to the live campaign with no Checker approval and will appear on the site immediately. The action is written to the audit log with who did it and when.', '2026-08-25 09:04:11.893+00', '2026-08-25 09:04:11.893+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (252, 'roleAwarePublishButton.forceAck', 'Bunun acil bir düzeltme olduğunu ve inceleme adımının bilerek atlandığını onaylıyorum.', 'I confirm this is an urgent fix and that the review step is being skipped deliberately.', '2026-08-25 09:04:11.903+00', '2026-08-25 09:04:11.903+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (253, 'roleAwarePublishButton.forceConfirm', 'Onayla ve Canlıya Uygula', 'Confirm & Apply Live', '2026-08-25 09:04:11.912+00', '2026-08-25 09:04:11.912+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (254, 'roleAwarePublishButton.submitFailed', 'Kaydedilemedi — zorunlu bir alan eksik olabilir ya da bu işlem için yetkiniz olmayabilir. Formdaki hata mesajlarını kontrol edip tekrar deneyin.', 'Couldn''t save — a required field may be missing, or you may not have permission. Check the form for errors and try again.', '2026-08-25 09:04:11.931+00', '2026-08-25 09:04:11.931+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (255, 'feedback.navLabel', 'Geri Bildirim Gönder', 'Send Feedback', '2026-08-25 09:04:11.942+00', '2026-08-25 09:04:11.942+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (256, 'feedback.title', 'Geri Bildirim Gönder', 'Send Feedback', '2026-08-25 09:04:11.952+00', '2026-08-25 09:04:11.952+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (257, 'feedback.intro', 'Bu paneli birlikte daha iyi hale getirelim. Kafanızı karıştıran, fazladan tıklama gerektiren ya da eksik bulduğunuz her şeyi buradan yazabilirsiniz — küçük bir detay bile olsa yazın, hepsini okuyoruz.', 'Let''s make this panel better together. Anything confusing, anything that takes too many clicks, anything missing — write it here. Even a small detail is worth sending; we read all of it.', '2026-08-25 09:04:11.96+00', '2026-08-25 09:04:11.96+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (258, 'feedback.areaLabel', 'İlgili Ekran / Bileşen', 'Screen / Component', '2026-08-25 09:04:11.968+00', '2026-08-25 09:04:11.968+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (259, 'feedback.areaPlaceholder', 'Örn: Kampanyalar → Yeni Oluştur, sürükle-bırak sıralama', 'E.g. Campaigns → Create New, drag-and-drop ordering', '2026-08-25 09:04:11.975+00', '2026-08-25 09:04:11.975+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (260, 'feedback.areaHint', 'Opsiyonel — hangi ekrandan bahsettiğinizi yazarsanız çok daha hızlı buluruz.', 'Optional — telling us which screen you mean helps us find it much faster.', '2026-08-25 09:04:11.981+00', '2026-08-25 09:04:11.981+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (261, 'feedback.messageLabel', 'Geri Bildiriminiz', 'Your Feedback', '2026-08-25 09:04:11.989+00', '2026-08-25 09:04:11.989+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (262, 'feedback.messagePlaceholder', 'Ne oldu, ne bekliyordunuz, sizce nasıl olmalıydı?', 'What happened, what did you expect, how do you think it should work?', '2026-08-25 09:04:11.998+00', '2026-08-25 09:04:11.998+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (263, 'feedback.send', 'Gönder', 'Send', '2026-08-25 09:04:12.007+00', '2026-08-25 09:04:12.007+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (264, 'feedback.sending', 'Gönderiliyor…', 'Sending…', '2026-08-25 09:04:12.015+00', '2026-08-25 09:04:12.015+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (265, 'feedback.thanks', 'Teşekkürler — geri bildiriminiz bize ulaştı.', 'Thank you — your feedback reached us.', '2026-08-25 09:04:12.024+00', '2026-08-25 09:04:12.024+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (266, 'feedback.error', 'Geri bildirim gönderilemedi. Lütfen tekrar deneyin.', 'Couldn''t send your feedback. Please try again.', '2026-08-25 09:04:12.031+00', '2026-08-25 09:04:12.031+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (267, 'feedback.privacy', 'Gönderdiğinizde kullanıcı adınız, rolünüz ve geldiğiniz ekran da kaydedilir — geri bildirimi doğru yere bağlayabilmemiz için.', 'Your username, role and the screen you came from are recorded with your message, so we can connect it to the right place.', '2026-08-25 09:04:12.039+00', '2026-08-25 09:04:12.039+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (268, 'categoryPeek.title', 'Bu akışta zaten olan kategoriler', 'Categories already in this flow', '2026-08-25 09:04:12.047+00', '2026-08-25 09:04:12.047+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (269, 'categoryPeek.loading', 'Yükleniyor…', 'Loading…', '2026-08-25 09:04:12.053+00', '2026-08-25 09:04:12.053+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (270, 'categoryPeek.empty', 'Bu akışta henüz başka kategori yok — ilkini siz oluşturuyorsunuz.', 'No other categories in this flow yet — you''re creating the first one.', '2026-08-25 09:04:12.061+00', '2026-08-25 09:04:12.061+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (271, 'categoryPeek.error', 'Mevcut kategoriler yüklenemedi.', 'Couldn''t load existing categories.', '2026-08-25 09:04:12.072+00', '2026-08-25 09:04:12.072+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (272, 'categoryPeek.note', 'Sadece bilgi amaçlıdır — aynısını tekrar oluşturmamanız için gösteriliyor.', 'Informational only — shown so you don''t create a duplicate.', '2026-08-25 09:04:12.082+00', '2026-08-25 09:04:12.082+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (273, 'autoSlug.label', 'Sayfa Adresi (otomatik)', 'Page URL (automatic)', '2026-08-25 09:04:12.091+00', '2026-08-25 09:04:12.091+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (274, 'autoSlug.liveHint', 'Başlığı yazdıkça otomatik oluşur — elle doldurmanız gerekmez. Kayıt sonrasında sabitlenir.', 'Generated automatically as you type the title — you don''t need to fill it in. It''s locked once saved.', '2026-08-25 09:04:12.1+00', '2026-08-25 09:04:12.1+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (275, 'autoSlug.frozenHint', 'Bu adres sabitlendi. Başlığı değiştirseniz bile adres değişmez — böylece daha önce paylaşılmış linkler bozulmaz.', 'This address is locked. Changing the title won''t change it, so links shared earlier keep working.', '2026-08-25 09:04:12.109+00', '2026-08-25 09:04:12.109+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (276, 'accessMatrix.searchPlaceholder', 'Koleksiyon ara…', 'Search collections…', '2026-08-25 09:04:12.115+00', '2026-08-25 09:04:12.115+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (277, 'accessMatrix.legendOff', 'soluk = yetki yok', 'faded = not granted', '2026-08-25 09:04:12.122+00', '2026-08-25 09:04:12.122+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (278, 'accessMatrix.noAccess', 'erişim yok', 'no access', '2026-08-25 09:04:12.129+00', '2026-08-25 09:04:12.129+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (279, 'accessMatrix.noMatch', 'Aramanızla eşleşen koleksiyon yok.', 'No collection matches your search.', '2026-08-25 09:04:12.136+00', '2026-08-25 09:04:12.136+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (280, 'feedback.countLabel', 'geri bildirim gönderildi', 'feedback submissions so far', '2026-08-25 11:39:16.283+00', '2026-08-25 11:39:16.282+00', false);
INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (281, 'roleAwarePublishButton.previewWidthGroup', 'önizleme genişliği', 'preview width', '2026-08-25 15:58:47.093+00', '2026-08-25 15:58:47.093+00', false);
