INSERT INTO public.translations (id, key, tr, en, updated_at, created_at, is_customized) VALUES (283, 'accountForm.avatarTooLarge', 'Profil fotoğrafı {maxMb}MB''den küçük olmalı.', 'Profile photo must be under {maxMb}MB.', '2026-08-25 15:58:47.135+00', '2026-08-25 15:58:47.135+00', false);
